import numpy as np
t=np.asarray(df['t']);P=np.asarray(df['P']);y=np.asarray(df['dP_dt'])
def fitcols(cols):
    X=np.column_stack(cols)
    c,_,_,_=np.linalg.lstsq(X,y,rcond=None)
    r=y-X@c
    return np.mean(r**2)/np.var(y), c
for deg in [2,4,6,8]:
    cols=[]
    for pw in [-1,0,1,2]:
        for k in range(deg+1):
            cols.append(t**k*P**pw)
    print('poly deg',deg, fitcols(cols)[0])
for deg in [4,6,8]:
    cols=[]
    for pw in [-1,0,1,2]:
        for k in range(deg+1):
            cols.append(t**k*P**pw)
        cols.append(P**pw*np.log(t))
    print('poly+log deg',deg, fitcols(cols)[0])
